var n=`1418-tuluk`;var t=`world-1418`;var s=`VU`;var i=`oceania`;var l=6;var o=101;var u={en:`Tuluk`,ua:`Тулук`};var r={en:`Tuluk is a Vanuatu cassava parcel filled with seasoned meat and baked in banana leaves. This home version uses cassava flour dough rather than freshly grated cassava.`,ua:`Тулук, страва Вануату із маніокового тіста з м’ясною начинкою в банановому листі. Домашня версія готується з маніокового борошна замість свіжого тертого кореня.`};var g=[{en:`Brown the ground pork in a skillet with onion and garlic until the meat reaches 71°C; stir in salt and set aside to cool slightly.`,ua:`Обсмажте свинячий фарш із цибулею та часником до температури 71°C у м’ясі; посоліть і трохи остудіть.`,t:[`sauteing`],m:13,i:[[`ground-pork`,420,`g`],[`yellow-onion`,110,`g`],[`garlic`,3,`clove`],[`sea-salt`,5,`g`],[`vegetable-oil-neutral`,15,`ml`]]},{en:`Mix cassava flour with a little salt and warm coconut milk until a soft pliable dough forms; rest 5 minutes.`,ua:`Змішайте маніокове борошно з невеликою кількістю солі й теплим кокосовим молоком до м’якого пластичного тіста; залиште на 5 хвилин.`,t:[`mixing`],m:10,i:[[`cassava-flour`,430,`g`],[`coconut-milk`,360,`ml`],[`sea-salt`,3,`g`]]},{en:`Soften food-safe banana leaves. Flatten six discs of dough, put pork filling in the middle and enclose securely in dough and leaf.`,ua:`Розм’якшіть харчове бананове листя. Розплескайте шість дисків тіста, покладіть усередину свинину й надійно загорніть у тісто та листя.`,t:[`leaf-wrapping`],m:18,i:[[`banana-leaf`,6,`leaf`]]},{en:`Arrange in a covered baking dish with a little water for steam; bake at 185°C for 45–55 minutes until the cassava dough has fully set and is cooked through.`,ua:`Викладіть у накриту форму з невеликою кількістю води для пари; запікайте при 185°C 45–55 хвилин, доки маніокове тісто не стане щільним і повністю готовим.`,t:[`steam-baking`],m:50,i:[[`water`,150,`ml`]]},{en:`Rest 10 minutes and unwrap carefully; serve warm.`,ua:`Дайте постояти 10 хвилин і обережно розгорніть; подавайте теплим.`,t:[`garnishing`],m:10,i:[]}];var d={slug:n,id:t,country:`VU`,region:i,servings:6,minutes:101,title:u,text:r,steps:g};export{s as country,d as default,t as id,o as minutes,i as region,l as servings,n as slug,g as steps,r as text,u as title};